/bin/zsh -lc "python3 - <<'PY'
from datetime import datetime
import cadence

p = {'timezone': 'UTC', 'rules': [
    {'id': 'paris', 'rule': 'every day at 12:00 for 1h from 1900-01-01 times 1', 'timezone': 'Europe/Paris'},
    {'id': 'utc', 'rule': 'every day at 11:51 for 1h from 1900-01-01 times 1', 'priority': 1},
]}
first, second = cadence.agenda(p, '1900-01-01T11:50Z', '1900-01-01T11:52Z')
print(first, second)
print('Apparent overlap:', datetime.fromisoformat(first['end']) - datetime.fromisoformat(second['start']))
edge = {'timezone': 'UTC', 'rules': [
    {'id': 'boundary', 'rule': 'every day at 23:00 for 2h from 9999-12-31 times 1'}
]}
bounds = ('9999-12-31T23:00Z', '9999-12-31T23:30Z')
try:
    cadence.occurrences(edge, *bounds)
except cadence.PlanError as exc:
    print(exc)
print(cadence.agenda(edge, *bounds))
PY"

